const publishGame = `-- name: PublishGame :one
UPDATE games
SET published_revision_id = $1, draft_revision_id = NULL, status = 'published',
    first_published_at = COALESCE(first_published_at, $2), revision_version = revision_version + 1,
    updated_at = now()
WHERE id = $3
RETURNING id, slug, platform, external_url, status, status_reason, link_status, link_checked_at, link_check_method, link_check_note, outbound_disabled, outbound_disabled_reason, featured, editorial_order, published_revision_id, draft_revision_id, revision_version, first_published_at, created_at, updated_at
`

